      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public partial class StressTestScene : MonoBehaviour
    {
        private StringBuilder _sb = new StringBuilder();

        private void Update()
        {
            if (stressGc)
            {
                _sb.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _sb.Append(i);
                }
                string s = _sb.ToString();
                GC.KeepAlive(s);

                for (int i = 0; i < gcArrayAllocs; i++)
                {
                    var block = new object[10000];
                    GC.KeepAlive(block);
                }
            }

            if (stressCpu)
            {
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    var allObjects = GameObject.FindObjectsOfType<GameObject>();
                    GC.KeepAlive(allObjects);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++) SpawnOne();
            }
        }
    }
}",
      "explicacao_didatica": "A coleta de lixo (conhecida como Garbage Collector ou GC) é o mecanismo da Unity responsável por liberar a memória que o jogo não está mais utilizando. No frame 170, a rotina de limpeza precisou pausar a execução por 22.75 ms para limpar mais de 5 MB de dados descartáveis gerados no mesmo quadro, consumindo cerca de um terço do tempo de CPU daquele instante. A concatenação contínua de texto com operador '+' cria novas cópias descartáveis de texto a cada iteração. O uso de StringBuilder reaproveita uma mesma área de memória interna para montar o texto, evitando alocações temporárias excessivas."
    }
  ],
  "dicas_level_design": null
}

